  1→import type { IDaemonRuntime } from "./runtime";
  2→import { DaemonMessageClaude, DaemonMessageSchema } from "./shared";
  3→import { performance } from "node:perf_hooks";
  4→import { Logger, type OutputFormat } from "./logger";
  5→
  6→type MessageBufferEntry = {
  7→  message: any;
  8→  entryId: string;
  9→  token: string;
 10→};
 11→
 12→export class test-projectDaemon {
 13→  private startTime: number = 0;
 14→  private messageBuffer: MessageBufferEntry[] = [];
 15→  private runtime: IDaemonRuntime;
 16→
 17→  private messageFlushDelay: number = 0;
 18→  private messageFlushTimer: NodeJS.Timeout | null = null;
 19→  private uptimeReportingInterval: number = 0;
 20→  private uptimeReportingTimer: NodeJS.Timeout | null = null;
 21→  private activeClaudeProcessId: number | null = null;
 22→  private isFlushInProgress: boolean = false;
 23→  private pendingFlushRequired: boolean = false;
 24→
 25→  constructor({
 26→    messageFlushDelay = 1000,
 27→    uptimeReportingInterval = 5000,
 28→    runtime,
 29→  }: {
 30→    messageFlushDelay?: number;
 31→    uptimeReportingInterval?: number;
 32→    runtime: IDaemonRuntime;
 33→  }) {
 34→    this.startTime = performance.now();
 35→    this.runtime = runtime;
 36→    this.messageFlushDelay = messageFlushDelay;
 37→    this.uptimeReportingInterval = uptimeReportingInterval;
 38→  }
 39→
 40→  /**
 41→   * Initialize and start the daemon
 42→   */
 43→  async start(): Promise<void> {
 44→    this.runtime.logger.info("🚀 Starting test-project Daemon...");
 45→    this.runtime.logger.info("Server URL configured", {
 46→      url: this.runtime.url,
 47→    });
 48→    this.runtime.logger.info("Named pipe configured", {
 49→      pipePath: this.runtime.pipePath,
 50→    });
 51→
 52→    // Start listening
 53→    await this.runtime.listen(this.handlePipeMessage.bind(this));
 54→    this.runtime.logger.info(
 55→      "✅ Daemon started successfully, waiting for messages...",
 56→    );
 57→
 58→    // Log every 5 seconds
 59→    this.uptimeReportingTimer = setInterval(() => {
 60→      const uptime = Math.round((performance.now() - this.startTime) / 1000);
 61→      this.runtime.logger.info("Daemon Heartbeat", { uptime: `${uptime}s` });
 62→    }, this.uptimeReportingInterval);
 63→    // Graceful shutdown handling
 64→    this.runtime.onTeardown(this.teardown.bind(this));
 65→  }
 66→
 67→  /**
 68→   * Handle incoming message
 69→   */
 70→  private async handlePipeMessage(message: string): Promise<void> {
 71→    try {
 72→      this.runtime.logger.info("Received pipe message", { message });
 73→      const jsonObj = JSON.parse(message);
 74→      const parsedMessage = DaemonMessageSchema.parse(jsonObj);
 75→      if (parsedMessage.type === "kill") {
 76→        this.runtime.logger.info("Killing daemon");
 77→        this.killActiveClaudeProcess();
 78→        return;
 79→      }
 80→      if (parsedMessage.type === "stop") {
 81→        this.runtime.logger.info(
 82→          "Stop message received, killing active claude process...",
 83→        );
 84→        this.killActiveClaudeProcess();
 85→        this.addMessageToBuffer({
 86→          message: { type: "custom-stop" },
 87→          entryId: parsedMessage.entryId,
 88→          token: parsedMessage.token,
 89→        });
 90→        await this.flushMessageBuffer();
 91→        return;
 92→      }
 93→      // Run the Claude command with this configuration
 94→      await this.runClaudeCommand(parsedMessage);
 95→    } catch (error) {
 96→      this.runtime.logger.error("Failed to process pipe message", { error });
 97→    }
 98→  }
 99→
100→  private killActiveClaudeProcess() {
101→    if (this.activeClaudeProcessId) {
102→      this.runtime.killChildProcessGroup(this.activeClaudeProcessId);
103→      this.activeClaudeProcessId = null;
104→      // TODO: Add a message to the buffer to indicate that the process was killed.
105→    }
106→  }
107→
108→  /**
109→   * Run the Claude command and process its output
110→   */
111→  private async runClaudeCommand(input: DaemonMessageClaude): Promise<void> {
112→    return new Promise((resolve) => {
113→      this.killActiveClaudeProcess();
114→      // Create the Claude command with the provided configuration
115→      const command = claudeCommand({
116→        prompt: input.prompt,
117→        sessionId: input.sessionId,
118→        model: input.model,
119→      });
120→      // Check if the user has Claude credentials.
121→      // If they do, we don't need to set the ANTHROPIC_API_KEY environment variable.
122→      // If they don't, we need to set it to the API key from the environment.
123→      const hasClaudeCredentials =
124→        this.runtime
125→          .execSync(
126→            "cd && test -f .claude/.credentials.json && echo 'EXISTS' || echo 'NOT_EXISTS'",
127→          )
128→          .trim() === "EXISTS";
129→      this.runtime.logger.info("Running Claude command", { command });
130→      const claudeProcessId = this.runtime.spawnCommand(
131→        "bash",
132→        ["-c", command],
133→        {
134→          env: {
135→            ...process.env,
136→            ANTHROPIC_API_KEY: hasClaudeCredentials
137→              ? ""
138→              : process.env.ANTHROPIC_API_KEY!,
139→            BASH_MAX_TIMEOUT_MS: (60 * 1000).toString(),
140→          },
141→          onStdoutLine: (line) => {
142→            this.runtime.logger.debug("Claude output", { line });
143→            if (line) {
144→              try {
145→                const outputMessage = JSON.parse(line);
146→                this.addMessageToBuffer({
147→                  message: outputMessage,
148→                  entryId: input.entryId,
149→                  token: input.token,
150→                });
151→              } catch (e) {
152→                this.runtime.logger.error(
153→                  "Failed to parse Claude output line",
154→                  {
155→                    line,
156→                    error: e,
157→                  },
158→                );
159→              }
160→            }
161→          },
162→          onStderr: (line) => {
163→            this.runtime.logger.error("Claude stderr", { line });
164→          },
165→          onError: (error) => {
166→            this.runtime.logger.error("Claude command error", { error });
167→          },
168→          onClose: (code) => {
169→            this.runtime.logger.info("Claude command finished", {
170→              exitCode: code,
171→            });
172→            if (this.activeClaudeProcessId === claudeProcessId) {
173→              this.activeClaudeProcessId = null;
174→            }
175→            if (code !== 0) {
176→              this.addMessageToBuffer({
177→                message: { type: "custom-error" },
178→                entryId: input.entryId,
179→                token: input.token,
180→              });
181→            }
182→            // Send any remaining messages in the buffer
183→            this.flushMessageBuffer();
184→            resolve();
185→          },
186→        },
187→      );
188→      this.runtime.logger.info("Spawned Claude process", {
189→        processId: claudeProcessId,
190→      });
191→
192→      if (claudeProcessId) {
193→        this.activeClaudeProcessId = claudeProcessId;
194→      }
195→    });
196→  }
197→
198→  /**
199→   * Add a message to the buffer and trigger debounced sending
200→   */
201→  private addMessageToBuffer(entry: MessageBufferEntry): void {
202→    this.messageBuffer.push(entry);
203→    this.runtime.logger.debug("Added message to buffer", {
204→      bufferSize: this.messageBuffer.length,
205→    });
206→
207→    // If a flush is in progress, mark that another flush is needed
208→    if (this.isFlushInProgress) {
209→      this.pendingFlushRequired = true;
210→      return;
211→    }
212→
213→    // Clear existing timer and set a new one
214→    if (this.messageFlushTimer) {
215→      clearTimeout(this.messageFlushTimer);
216→    }
217→    this.messageFlushTimer = setTimeout(() => {
218→      this.flushMessageBuffer();
219→    }, this.messageFlushDelay);
220→  }
221→
222→  /**
223→   * Send all buffered messages to the API and clear the buffer
224→   */
225→  private async flushMessageBuffer(): Promise<void> {
226→    // Prevent concurrent flushes
227→    if (this.isFlushInProgress) {
228→      this.pendingFlushRequired = true;
229→      return;
230→    }
231→
232→    if (this.messageBuffer.length === 0) {
233→      return;
234→    }
235→
236→    this.isFlushInProgress = true;
237→    this.pendingFlushRequired = false;
238→
239→    if (this.messageFlushTimer) {
240→      clearTimeout(this.messageFlushTimer);
241→      this.messageFlushTimer = null;
242→    }
243→
244→    const messageBufferCopy = [...this.messageBuffer];
245→    this.messageBuffer = [];
246→
247→    // Use the entryId and token of the last entry in the buffer.
248→    const lastEntry = messageBufferCopy[messageBufferCopy.length - 1];
249→    const entryId = lastEntry.entryId;
250→    const token = lastEntry.token;
251→
252→    let apiCallSucceeded = false;
253→    try {
254→      await this.sendMessagesToAPI(
255→        messageBufferCopy.map((m) => m.message),
256→        token,
257→        entryId,
258→      );
259→      apiCallSucceeded = true;
260→    } catch (error) {
261→      // On API failure, put the messages back at the beginning of the buffer
262→      this.runtime.logger.error("API call failed, will retry messages", {
263→        error,
264→        messageCount: messageBufferCopy.length,
265→      });
266→      this.messageBuffer = [...messageBufferCopy, ...this.messageBuffer];
267→      this.pendingFlushRequired = true;
268→    } finally {
269→      this.isFlushInProgress = false;
270→
271→      // If new messages arrived while we were flushing, or if we need to retry
272→      if (this.pendingFlushRequired && this.messageBuffer.length > 0) {
273→        this.messageFlushTimer = setTimeout(() => {
274→          this.flushMessageBuffer();
275→        }, this.messageFlushDelay);
276→      }
277→    }
278→  }
279→
280→  /**
281→   * Send an array of messages to the API endpoint
282→   */
283→  private async sendMessagesToAPI(
284→    messages: any[],
285→    token: string,
286→    entryId: string,
287→  ): Promise<void> {
288→    try {
289→      this.runtime.logger.info("Sending messages to API", {
290→        messageCount: messages.length,
291→        entryId,
292→      });
293→      await this.runtime.serverPost({ messages, entryId }, token);
294→      this.runtime.logger.info("Messages sent successfully", {
295→        messageCount: messages.length,
296→      });
297→    } catch (error) {
298→      this.runtime.logger.error("Failed to send messages to API", {
299→        error,
300→        messageCount: messages.length,
301→      });
302→      // Re-throw the error so flushMessageBuffer can handle it
303→      throw error;
304→    }
305→  }
306→
307→  private async teardown(): Promise<void> {
308→    // Send any remaining messages in the buffer
309→    this.killActiveClaudeProcess();
310→    await this.flushMessageBuffer();
311→    // Send a kill message to the pipe to flush our blocking listeners.
312→    await this.runtime.writeToNamedPipe({ type: "kill" });
313→    if (this.uptimeReportingTimer) {
314→      clearInterval(this.uptimeReportingTimer);
315→    }
316→    if (this.messageFlushTimer) {
317→      clearTimeout(this.messageFlushTimer);
318→    }
319→  }
320→}
321→
322→function claudeCommand({
323→  prompt,
324→  sessionId,
325→  model,
326→}: {
327→  prompt: string;
328→  sessionId: string | null;
329→  model: "opus" | "sonnet";
330→}) {
331→  const parts = [
332→    "echo",
333→    `"${prompt.replace(/"/g, '\\"')}"`,
334→    "|",
335→    "claude",
336→    "-p",
337→    "--model",
338→    model,
339→    sessionId ? `--resume ${sessionId}` : "",
340→    "--verbose",
341→    "--dangerously-skip-permissions",
342→    "--output-format",
343→    "stream-json",
344→    sessionId ? `--resume ${sessionId}` : "",
345→    "--append-system-prompt",
346→    '"Your name is Toothless and you are a coding agent that works for test-project Labs."',
347→  ];
348→  return parts.join(" ");
349→}
