  1→/**
  2→ * Provides runtime context and system operations for the daemon.
  3→ */
  4→
  5→import { exec, execSync, spawn } from "node:child_process";
  6→import EventEmitter from "node:events";
  7→import fs from "node:fs";
  8→import readline from "node:readline";
  9→import stripAnsi from "strip-ansi";
 10→import { Logger, OutputFormat } from "./logger";
 11→
 12→export interface IDaemonRuntime {
 13→  url: string;
 14→  pipePath: string;
 15→  readonly logger: Logger;
 16→
 17→  teardown: () => Promise<void>;
 18→  onTeardown: (callback: () => Promise<void> | void) => void;
 19→
 20→  serverPost: (body: any, token: string) => Promise<void>;
 21→
 22→  listen: (callback: (data: string) => void) => Promise<void>;
 23→  writeToNamedPipe: (data: any, timeout?: number) => Promise<void>;
 24→
 25→  exitProcess: () => void;
 26→  killChildProcessGroup: (pid: number) => void;
 27→  execSync: (command: string) => string;
 28→  spawnCommand: (
 29→    command: string,
 30→    args: string[],
 31→    {
 32→      env,
 33→      onStdoutLine,
 34→      onStderr,
 35→      onError,
 36→      onClose,
 37→    }: {
 38→      env: Record<string, string>;
 39→      onStdoutLine: (line: string) => void;
 40→      onStderr: (data: string) => void;
 41→      onError: (error: Error) => void;
 42→      onClose: (code: number | null) => void;
 43→    },
 44→  ) => number | undefined;
 45→}
 46→
 47→export class DaemonRuntime implements IDaemonRuntime {
 48→  readonly url: string;
 49→  readonly pipePath: string;
 50→  readonly logger: Logger;
 51→  private isTerminated = false;
 52→  private eventEmitter = new EventEmitter();
 53→
 54→  constructor({
 55→    url,
 56→    pipePath,
 57→    outputFormat,
 58→  }: {
 59→    url: string;
 60→    pipePath: string;
 61→    outputFormat: OutputFormat;
 62→  }) {
 63→    this.url = url;
 64→    this.pipePath = pipePath;
 65→    this.logger = new Logger(outputFormat);
 66→    try {
 67→      // Remove existing pipe if it exists
 68→      if (fs.existsSync(this.pipePath)) {
 69→        fs.unlinkSync(this.pipePath);
 70→      }
 71→      // Create using mkfifo command
 72→      execSync(`mkfifo "${this.pipePath}"`);
 73→      // Set permissions
 74→      execSync(`chmod 666 "${this.pipePath}"`);
 75→    } catch (error) {
 76→      this.logger.error("Failed to create", { error });
 77→      throw error;
 78→    }
 79→    process.on("SIGTERM", () => {
 80→      this.teardown();
 81→    });
 82→    process.on("SIGINT", () => {
 83→      this.teardown();
 84→    });
 85→  }
 86→
 87→  async teardown() {
 88→    if (this.isTerminated) {
 89→      return;
 90→    }
 91→    this.isTerminated = true;
 92→    await Promise.allSettled(
 93→      this.eventEmitter.listeners("teardown").map((fn) => fn()),
 94→    );
 95→    if (fs.existsSync(this.pipePath)) {
 96→      fs.unlinkSync(this.pipePath);
 97→    }
 98→    this.exitProcess();
 99→  }
100→
101→  execSync(command: string) {
102→    return execSync(command, {
103→      encoding: "utf-8",
104→    });
105→  }
106→
107→  exitProcess() {
108→    // Ideally we can use process.exit(0) here, but if we have active handles
109→    // or requests, the process will not exit properly. So lets kill the process
110→    // forcefully.
111→    process.kill(-process.pid, "SIGKILL");
112→  }
113→
114→  onTeardown(callback: () => Promise<void> | void) {
115→    this.eventEmitter.on("teardown", callback);
116→  }
117→
118→  async serverPost(body: any, token: string) {
119→    this.logger.info(`POST to ${this.url}/api/daemon-event`, {
120→      url: `${this.url}/api/daemon-event`,
121→      body: JSON.stringify(body),
122→    });
123→    const response = await fetch(`${this.url}/api/daemon-event`, {
124→      method: "POST",
125→      headers: {
126→        "Content-Type": "application/json",
127→        "X-Daemon-Token": token,
128→      },
129→      body: JSON.stringify(body),
130→    });
131→    if (!response.ok) {
132→      throw new Error(`HTTP error! status: ${response.status}`);
133→    }
134→  }
135→
136→  async listen(callback: (data: string) => void) {
137→    if (this.isTerminated) {
138→      return;
139→    }
140→    if (!fs.existsSync(this.pipePath)) {
141→      this.logger.error("Pipe does not exist", { pipePath: this.pipePath });
142→      return;
143→    }
144→    const stream = fs.createReadStream(this.pipePath, {
145→      encoding: "utf8",
146→    });
147→    // Use readline for line-by-line processing
148→    const rl = readline.createInterface({
149→      input: stream,
150→      crlfDelay: Infinity, // Handle Windows line endings properly
151→    });
152→    rl.on("line", (line) => {
153→      if (line.trim()) {
154→        callback(line.trim());
155→      }
156→    });
157→    rl.on("close", () => {
158→      // Only restart if not terminated
159→      if (!this.isTerminated) {
160→        this.listen(callback);
161→      }
162→    });
163→    stream.on("end", () => {
164→      rl.close();
165→    });
166→    stream.on("error", (error) => {
167→      this.logger.error("Pipe stream error", { error });
168→    });
169→    // Wait for the pipe to be ready
170→    await new Promise((resolve) => setTimeout(resolve, 0));
171→  }
172→
173→  async writeToNamedPipe(data: any, timeout: number = 100) {
174→    await Promise.race([
175→      new Promise((_, reject) =>
176→        setTimeout(() => {
177→          reject(
178→            new Error(
179→              `Timeout after ${timeout}ms. It is likely that the pipe is not ready to be written to. This is probably because the reader is not running.`,
180→            ),
181→          );
182→        }, timeout),
183→      ),
184→      new Promise<void>((resolve, reject) => {
185→        exec(`echo '${JSON.stringify(data)}' > "${this.pipePath}"`, (err) => {
186→          if (err) {
187→            this.logger.error("Error writing to pipe", { error: err });
188→            reject(err);
189→            return;
190→          }
191→          resolve();
192→        });
193→      }),
194→    ]);
195→  }
196→
197→  killChildProcessGroup(pid: number) {
198→    try {
199→      process.kill(-pid, "SIGKILL");
200→    } catch (error) {
201→      this.logger.error("Error killing child process group", { error });
202→    }
203→  }
204→
205→  spawnCommand(
206→    command: string,
207→    args: string[],
208→    {
209→      env,
210→      onStdoutLine,
211→      onStderr,
212→      onError,
213→      onClose,
214→    }: {
215→      env: Record<string, string>;
216→      onStdoutLine: (line: string) => void;
217→      onStderr: (data: string) => void;
218→      onError: (error: Error) => void;
219→      onClose: (code: number | null) => void;
220→    },
221→  ): number | undefined {
222→    const child = spawn(command, args, {
223→      env,
224→      detached: true,
225→      stdio: ["inherit", "pipe", "pipe"],
226→    });
227→    // Use readline to process output line by line
228→    if (child.stdout) {
229→      const rl = readline.createInterface({
230→        input: child.stdout,
231→        crlfDelay: Infinity, // Handle Windows line endings properly
232→      });
233→      rl.on("line", (line) => {
234→        if (line.trim()) {
235→          onStdoutLine(stripAnsi(line));
236→        }
237→      });
238→    } else {
239→      this.logger.warn("No stdout available");
240→    }
241→    if (child.stderr) {
242→      child.stderr.on("data", (data: Buffer) => {
243→        const output = data.toString();
244→        onStderr(output);
245→      });
246→    } else {
247→      this.logger.warn("No stderr available");
248→    }
249→    child.on("close", (code) => {
250→      onClose(code);
251→    });
252→    child.on("error", (error) => {
253→      onError(error);
254→    });
255→    return child.pid;
256→  }
257→}
