  1→import { DaemonMessageStop, DaemonMessageClaude } from "../shared";
  2→import { DaemonRuntime } from "../runtime";
  3→import { test-projectDaemon } from "../daemon";
  4→import {
  5→  describe,
  6→  it,
  7→  expect,
  8→  vi,
  9→  beforeEach,
 10→  afterEach,
 11→  MockInstance,
 12→} from "vitest";
 13→import { nanoid } from "nanoid/non-secure";
 14→
 15→async function sleep(ms: number = 10) {
 16→  return new Promise((resolve) => setTimeout(resolve, ms));
 17→}
 18→
 19→const TEST_INPUT_MESSAGE: DaemonMessageClaude = {
 20→  type: "claude",
 21→  token: "TEST_TOKEN_STRING",
 22→  prompt: "TEST_PROMPT_STRING",
 23→  sessionId: null,
 24→  model: "opus",
 25→  entryId: "TEST_entry_ID_STRING",
 26→};
 27→
 28→const TEST_STOP_MESSAGE: DaemonMessageStop = {
 29→  type: "stop",
 30→  entryId: "TEST_entry_ID_STRING",
 31→  token: "TEST_TOKEN_STRING",
 32→};
 33→
 34→describe("daemon", () => {
 35→  let runtime: DaemonRuntime;
 36→  let daemon: test-projectDaemon;
 37→  let killChildProcessGroupMock: MockInstance<
 38→    DaemonRuntime["killChildProcessGroup"]
 39→  >;
 40→  let spawnCommandMock: MockInstance<DaemonRuntime["spawnCommand"]>;
 41→  let serverPostMock: MockInstance<DaemonRuntime["serverPost"]>;
 42→  let execSyncMock: MockInstance<DaemonRuntime["execSync"]>;
 43→
 44→  beforeEach(() => {
 45→    const pipePath = `/tmp/test-project-daemon-${nanoid()}.pipe`;
 46→    runtime = new DaemonRuntime({
 47→      url: "http://localhost:3000",
 48→      pipePath,
 49→      outputFormat: "text",
 50→    });
 51→    vi.spyOn(runtime, "listen");
 52→    vi.spyOn(runtime, "exitProcess").mockImplementation(() => {});
 53→    killChildProcessGroupMock = vi
 54→      .spyOn(runtime, "killChildProcessGroup")
 55→      .mockImplementation(() => {});
 56→    spawnCommandMock = vi
 57→      .spyOn(runtime, "spawnCommand")
 58→      .mockImplementation(() => undefined);
 59→    serverPostMock = vi.spyOn(runtime, "serverPost").mockResolvedValue();
 60→    execSyncMock = vi
 61→      .spyOn(runtime, "execSync")
 62→      .mockReturnValue("NOT_EXISTS\n");
 63→    daemon = new test-projectDaemon({
 64→      runtime,
 65→      messageFlushDelay: 10,
 66→    });
 67→  });
 68→
 69→  function mockSpawnCommandStdoutLine(claudeMessage: any) {
 70→    spawnCommandMock.mock.calls[0][2].onStdoutLine(
 71→      JSON.stringify(claudeMessage),
 72→    );
 73→  }
 74→
 75→  afterEach(async () => {
 76→    vi.clearAllMocks();
 77→    await runtime.teardown();
 78→  });
 79→
 80→  it("should kill the active claude process when another message is received", async () => {
 81→    spawnCommandMock.mockReturnValue(1234);
 82→
 83→    await daemon.start();
 84→    await runtime.writeToNamedPipe(TEST_INPUT_MESSAGE);
 85→    await sleep();
 86→
 87→    expect(spawnCommandMock).toHaveBeenCalledTimes(1);
 88→    expect(killChildProcessGroupMock).toHaveBeenCalledTimes(0);
 89→
 90→    await runtime.writeToNamedPipe(TEST_INPUT_MESSAGE);
 91→    await sleep();
