 1→import { redis } from "./redis";
 2→import { Ratelimit } from "@upstash/ratelimit";
 3→
 4→const PREFIX = "@upstash/ratelimit";
 5→
 6→const sandboxCreationRateLimit = new Ratelimit({
 7→  redis,
 8→  limiter: Ratelimit.tokenBucket(
 9→    process.env.NODE_ENV === "production" ? 10 : 1000, // refillRate
10→    "1h", // window
11→    process.env.NODE_ENV === "production" ? 10 : 1000, // maxTokens
12→  ),
13→  prefix: `${PREFIX}:sandbox-creation`,
14→});
15→
16→export const testRateLimit = new Ratelimit({
17→  redis,
18→  limiter: Ratelimit.tokenBucket(
19→    10, // refillRate
20→    "10s", // window
21→    10, // maxTokens
22→  ),
23→  prefix: `${PREFIX}:test`,
24→});
25→
26→export async function throwIfRateLimited(rateLimit: Ratelimit, key: string) {
27→  const result = await rateLimit.limit(key);
28→  if (!result.success) {
29→    throw new Error(
30→      `Rate limit exceeded: ${result.remaining} remaining, reset in ${result.reset}`,
31→    );
32→  }
33→}
34→
35→export async function trackSandboxCreationOrThrow(userId: string) {
36→  return throwIfRateLimited(sandboxCreationRateLimit, userId);
37→}
38→
39→export async function trackTestOrThrow(key: string) {
40→  return throwIfRateLimited(testRateLimit, key);
41→}
