 18→export async function POST(request: Request) {
 19→  let { messages, entryId } = await request.json();
 20→  console.log(
 21→    "Daemon event",
 22→    "entryId",
 23→    entryId,
 24→    "messages",
 25→    JSON.stringify(messages, null, 2),
 26→  );
 27→
 28→  const token = request.headers.get("X-Daemon-Token");
 29→  if (!token) {
 30→    console.log("No token");
 31→    return new Response("Unauthorized", { status: 401 });
 32→  }
 33→  const { valid, error, key } = await auth.api.verifyApiKey({
 34→    body: {
 35→      key: token,
 36→    },
 37→  });
 38→  const userId = key?.userId;
 39→  if (error || !valid || !userId) {
 40→    console.log(
 41→      "Unauthorized",
 42→      "error",
 43→      error,
 44→      "valid",
 45→      valid,
 46→      "userId",
 47→      userId,
 48→    );
 49→    return new Response("Unauthorized", { status: 401 });
 50→  }
 51→  const entry = await getentry({
 52→    db,
 53→    entryId,
 54→    userId,
 55→  });
 56→  if (!entry) {
 57→    return new Response("entry not found", { status: 404 });
 58→  }
 59→
 60→  // On every daemon event, we set the daemon status to active.
 61→  waitUntil(setDaemonStatus(entry.codesandboxId!, "active"));
 62→
 63→  // Extend the life of the sandbox.
 64→  const sandboxProvider = getSandboxProvider(entry.sandboxProvider);
 65→  waitUntil(sandboxProvider.extendLife(entry.codesandboxId!));
 66→
 67→  const isStop = messages.some(
 68→    (message: ClaudeMessage) => message.type === "custom-stop",
 69→  );
 70→  const isDone = messages.some(
 71→    (message: ClaudeMessage) => message.type === "result",
 72→  );
 73→  const isError = messages.some(
 74→    (message: ClaudeMessage) => message.type === "custom-error",
 75→  );
 76→  const sessionId: string | null = messages
 77→    .map((message: ClaudeMessage) => message.session_id)
 78→    .find((sessionId: string | null) => sessionId != null);
 79→
 80→  const dbMessages: DBMessage[] = [];
 81→
 82→  for (const message of messages) {
 83→    const dbMessage = toDBMessage(message);
 84→    dbMessages.push(...dbMessage);
 85→  }
 86→
 87→  let finalMessages = [...(entry.messages ?? []), ...dbMessages];
