/**
 * Calculate retry delay with exponential backoff
 */
private calculateRetryDelay(): number {
  const exponentialDelay = this.baseRetryDelay * Math.pow(this.backoffMultiplier, this.retryCount);
  // Add jitter to prevent thundering herd
  const jitter = Math.random() * 0.3 * exponentialDelay; // 0-30% jitter
  const delayWithJitter = exponentialDelay + jitter;
  // Cap at maximum delay
  return Math.min(delayWithJitter, this.maxRetryDelay);
}

/**
 * Open the circuit breaker after too many consecutive failures
 */
private openCircuitBreaker(): void {
  this.isCircuitOpen = true;
  this.runtime.logger.error("Circuit breaker OPENED - stopping retries temporarily", {
    consecutiveFailures: this.consecutiveFailures,
    cooldownMs: this.circuitBreakerCooldown,
  });

  // Set timer to attempt closing the circuit after cooldown
  this.circuitBreakerTimer = setTimeout(() => {
    this.runtime.logger.info("Attempting to close circuit breaker");
    this.isCircuitOpen = false;
    this.consecutiveFailures = 0;
    this.retryCount = 0;

    // Try to flush any pending messages
    if (this.messageBuffer.length > 0) {
      this.flushMessageBuffer();
    }
  }, this.circuitBreakerCooldown);
}

/**
 * Close the circuit breaker after successful communication
 */
private closeCircuitBreaker(): void {
  this.isCircuitOpen = false;
  if (this.circuitBreakerTimer) {
    clearTimeout(this.circuitBreakerTimer);
    this.circuitBreakerTimer = null;
  }
  this.runtime.logger.info("Circuit breaker CLOSED - normal operation resumed");
}

